```dart
   @override
   Stream<List<NewsModel>> loadNewsFeedStream(NewsFeedFilter filter) {
     final controller = StreamController<List<NewsModel>>();

     // Emit cached data immediately for instant display
     _dbDatasource.getNewsList().then((cached) {
       if (controller.hasListener) {
